generate.initial_sparql:
PREFIX wm: <https://wealth.example.org/ontology/>
PREFIX kg: <https://wealth.example.org/kg/>
PREFIX wmmeta: <https://wealth.example.org/metadata/>
PREFIX rdfs: <http://www.w3.org/2000/01/rdf-schema#>
PREFIX schema1: <http://schema.org/>
PREFIX rdf: <http://www.w3.org/1999/02/22-rdf-syntax-ns#>
PREFIX xsd: <http://www.w3.org/2001/XMLSchema#>

SELECT 
  (AVG(xsd:decimal(?riskScore)) AS ?avgRiskScore)
  (AVG(xsd:decimal(?liquidityScore)) AS ?avgLiquidityScore)
  (AVG(xsd:decimal(?diversificationScore)) AS ?avgDiversificationScore)
  (AVG(xsd:decimal(?goalMatchPct)) AS ?avgGoalMatchPct)
WHERE {
  ?ph a wm:PortfolioHealth .
  OPTIONAL { ?ph wm:riskScore ?riskScore . }
  OPTIONAL { ?ph wm:liquidityScore ?liquidityScore . }
  OPTIONAL { ?ph wm:diversificationScore ?diversificationScore . }
  OPTIONAL { ?ph wm:goalMatchPct ?goalMatchPct . }
}

